SELECT p.id, '***' AS title, h.score FROM qod_search((SELECT rowid FROM lake.main.pages WHERE lang = 'fr'), 'lake.main.pages', ['body'], 'w1 w10') h JOIN lake.main.pages p ON p.rowid = h.rowid ORDER BY h.score DESC
SELECT p.f10, count(*) AS n FROM qod_search_matches((SELECT rowid FROM lake.main.pages WHERE lang = 'fr'), 'lake.main.pages', ['body'], 'w1 w10') m JOIN lake.main.pages p ON p.rowid = m.rowid GROUP BY ALL ORDER BY n DESC
SELECT p.id, p.title, h.score FROM qod_search((SELECT rowid FROM lake.main.pages WHERE lower(lang) = 'fr'), 'lake.main.pages', ['body'], 'w1 w10') h JOIN lake.main.pages p ON p.rowid = h.rowid ORDER BY h.score DESC
SELECT z.id, '***' AS title, h.score FROM qod_search((SELECT q.rowid FROM pages q), 'pages', ['body'], 'w1 w10') h JOIN pages AS z ON z.rowid = h.rowid
SELECT p.id, '***' AS title FROM qod_search((SELECT rowid FROM main.pages), 'main.pages', ['body'], 'w1 w10', k := 5) h JOIN main.pages p ON p.rowid = h.rowid
SELECT p.id, '***' AS title, h.score FROM qod_search((SELECT rowid FROM (SELECT *, rowid FROM lake.main.pages WHERE (f10 = 0)) AS pages WHERE lang = 'fr'), 'lake.main.pages', ['body'], 'w1 w10') h JOIN (SELECT *, rowid FROM lake.main.pages WHERE (f10 = 0)) p ON p.rowid = h.rowid ORDER BY h.score DESC
